#include <fcntl.h>   // open、O_RDONLY
#include <unistd.h>  // close
#include <cstdio>    // printf、perror
#include <cerrno>

bool write_all(int out_fd, const char* data, size_t total) {
    size_t done = 0;

    while (done < total) {
        ssize_t written = write(out_fd, data, total-done);

        if (written < 0) {
            if (errno == EINTR) {
                continue;
            }
            std::perror("write");
            return false;
        }

        if (written == 0) {
            std::fprintf(stderr, "write: no progress\n");
            return false;
        }

        done += written;
    }

    return true;
}
int main() {
    int fd = open("gpu-kernel-lab/results/raw/2026-10-27-fd-input.txt", O_RDONLY);
    if (fd < 0) {
        std::perror("open");
        return 1;
    }

    std::printf("fd=%d\n", fd);
   char buf[4];

while (true) {
    ssize_t n = read(fd, buf, sizeof(buf));

    if (n < 0) {
        std::perror("read");
        close(fd);
        return 1;
    }

    std::printf("read=%zd\n", n);

    if (n == 0) {
        break;
    }
}

    if (close(fd) < 0) {
        std::perror("close");
        return 1;
    }

    return 0;
}

